participante = {}
inicio = false
fim = false
qtd = 0
fast = 0
ganhadores = {}
local sorteioEmAndamento = false
tfm.exec.disableAfkDeath(true)

-- tabela para armazenar os jogadores banidos, siga o padrão para adicionar mais players

