function eventTextAreaCallback(id, p, cmd)
    if cmd == "entrada" then
        ui.addTextArea(0, "<p align='center'>Participando", p, 1200, 370, 340, 20, 1, 0x00FF00, 0, false)
        setPlayerNameColorGreen(p)
        entrada(p, #participante + 1)
    elseif cmd == "inicio" then
        ui.addPopup(0, 2, "<p align='center'>Quantidade de sorteados", p, 1620, 430, 200, false)
    elseif cmd == "terminar" then
        terminar()
    elseif cmd == "reviver" then
        reviver(p)
    elseif cmd == "lista" then
        verLista(p)
    elseif cmd == "novo" then
        novo()
    elseif cmd == "verGanhadores" then
        verGanhadores(p)
    elseif cmd == "fecharGanhadores" then
        fecharGanhadores(p)
    elseif cmd == "fechar" then
        fecharLista(p)
		elseif cmd == "fogos" then
			executarfogos()
    elseif cmd == "discord" then
        ui.addPopup(0, 2, "<p align='center'>❥ Nosso servidor: discord.gg/RDc33tqpGM", p, 620, 430, 340, false)
    elseif cmd == "whatsapp" then
        ui.addPopup(0, 2, "<p align='center'>❥ Canal oficial: chat.whatsapp.com/K0WEHHQAIj2C51hvmGNysH", p, 620, 230, 440, false)
    end
end

function entrada(p, num)
    if not participando(p) then
        participante[num] = p
    end
end

function reviver(p)
    tfm.exec.respawnPlayer(p)
end

function eventoGanhador(nomeGanhador)
    table.insert(ganhadores, nomeGanhador)
end

function sortearGanhador()
    local ganhador
    repeat
        ganhador = math.random(1, #participante)
    until not ganhadores[ganhador]
    return ganhador
end

function terminar()
    -- Aqui você adiciona um erro intencional para encerrar o script
    error("Script encerrado intencionalmente") 
end

function eventPopupAnswer(id, p, cmd)
    if tonumber(cmd, 10) then
        if tonumber(cmd, 10) >= 1 and tonumber(cmd, 10) <= #participante then
            ui.removeTextArea(0, nil)
            ui.removeTextArea(-1, nil)
            qtd = tonumber(cmd, 10)
            fast = math.random(25, 30)
            inicio = true
        end
    end
end

function eventNewPlayer(p)
		tfm.exec.respawnPlayer(p)
    if not inicio and not fim then
			ui.addTextArea(-15, "<p align='center'><font size='12' color='#ttFFtt'>※ AVISO:<font size='12' color='#9AEBA3'> todos os sabados as 20:30 teremos sorteios de queijos no cafofo da tribo!", nil, 1570, 425, 580, 22, 1, 0x000000, 0.85, false)
			ui.addTextArea(-7, "<p align='center'><a href='event:verGanhadores'>Ver Ganhadores", nil, 1290, 780, 150, 20, 1, 0x00FFFF, 0.5, false)
