function eventLoop()
for _, jogador in ipairs(jogadoresBanidos) do
    ui.removeTextArea(0, jogador)
    tfm.exec.setNameColor(jogador, 0xFF0000) -- Muda a cor para vermelho
end

    if inicio then
        if fast > 0 then
            sorteioEmAndamento = true  -- Sorteio está em andamento
					tfm.exec.playSound('/cite18/rubis.mp3', 100, nil, nil, nil)
					ui.addTextArea(1000, "<p align='center'><font color='#E7B200'><b>Processando...", nil, 1600, 760, 400, 20, 1, 0xFECCFF, 0, false)
            local ganhador = sortearGanhador()
            if ganhador then
                mostrarGanhador(ganhador)
                fast = fast - 1
            end
        else
            sorteioEmAndamento = false  -- Sorteio não está em andamento
            inicio = false
            fim = true
            ui.addTextArea(-12, "<p align='center'><a href='event:novo'>Novo sorteio", adm, 1860, 780, 100, 20, 1, 0xFF00FF, 0.5, false)
            ui.addTextArea(-1, "<p align='center'><a href='event:terminar'>Finalizar SCRIPT", adm, 1990, 780, 150, 20, 1, 0x0000FF, 0.5, false)
            local ganhador = sortearGanhador()

            if ganhador then
					tfm.exec.playSound('/deadmaze/sons/17.mp3', 100, nil, nil, nil)
                tfm.exec.giveCheese(participante[ganhador])
                tfm.exec.setNameColor(participante[ganhador], 0xFFCC23)
                eventoGanhador(participante[ganhador])
    				ui.removeTextArea(ganhador, nil)
    				ui.addTextArea(ganhador, "<p align='center'><font size='30' color='#5CFF00'>" .. participante[ganhador], nil, 1700, 550, 300, 40, 1, 0x5CFF00, 1, false)
                ui.addTextArea(1000, "<p align='center'><font color='#00FF1B'><b>Sorteio encerrado!", nil, 1600, 760, 400, 20, 1, 0x6E27FD, 0, false)
					tfm.exec.movePlayer(participante[ganhador], 1720, 540)
                tfm.exec.playEmote (participante[ganhador], 0, nil)
            end
        end
    end
end



function participando(p)
    for i, v in pairs(participante) do
        if v == p then
            return true
        end
    end
    return false
end

function mostrarGanhador(ganhador)
    for i = 1, #participante do
        if i ~= ganhador then
            ui.removeTextArea(i, nil)
        end
    end

    coresaleatorio = math.random(0, 5)
    if sorteioEmAndamento == true then
 		if coresaleatorio == 0 then
			   corTexto = "#FF0000"
			elseif coresaleatorio == 1 then
			   corTexto = "#FF7100"
			elseif coresaleatorio == 2 then
			   corTexto = "#FFD700"
 		elseif coresaleatorio == 3 then
			   corTexto = "#22E5FF"
			elseif coresaleatorio == 4 then
			   corTexto = "#C5FF22"
			elseif coresaleatorio == 5 then
			   corTexto = "#F100FF"
			end
		end

    ui.addTextArea(ganhador, "<p align='center'><font size='30' color='" ..corTexto.. "'>" .. participante[ganhador], nil, 1700, 550, 400, 80, 1, 1, 0, false)
end

