function eventTextAreaCallback(id, p, cmd)
    if cmd == "entrada" then
        ui.addTextArea(0, "<p align='center'>Participando", p, 1630, 780, 340, 20, 1, 0x00FF00, 0.8, false)
        entrada(p, #participante + 1)
        setPlayerNameColorGreen(p)
    elseif cmd == "inicio" then
        ui.addPopup(0, 2, "<p align='center'>Quantidade de sorteados", p, 1620, 630, 200, false)
    elseif cmd == "terminar" then
        terminar()
    elseif cmd == "reviver" then
        reviver(p)
    elseif cmd == "lista" then
        verLista(p)
    elseif cmd == "novo" then
        novo()
    elseif cmd == "verGanhadores" then
        verGanhadores(p) -- Chama a função para exibir a lista de ganhadores
    elseif cmd == "fecharGanhadores" then
        fecharGanhadores(p) -- Chama a função para fechar a lista de ganhadores
    elseif cmd == "fechar" then
        fecharLista(p)
		elseif cmd == "fogos" then
			executarfogos()
    elseif cmd == "discord" then
        ui.addPopup(0, 2, "<p align='center'>❥ Nosso servidor: discord.gg/RDc33tqpGM", p, 1620, 430, 340, false)
    elseif cmd == "whatsapp" then
        ui.addPopup(0, 2, "<p align='center'>❥ Canal oficial: chat.whatsapp.com/K0WEHHQAIj2C51hvmGNysH", p, 1620, 430, 340, false)
    end
end

